_logger.info(f"Ejecutar Webhook app/uninstalled.")
if record.external_id and record.bearer_token:
    try:
        ResCompany = env['res.company'].sudo()
        store_id = payload.get('store_id')
        if record.external_id == store_id:
            company_id = record
        else:
            company_id = ResCompany.search([('external_id', '=', store_id)])
        if company_id:
            # desactivar los webhooks de la empresa en TN
            wh_ids = env['solt.register.webhook'].search([('company_id', '=', company_id.id), ('connector_id', '=', base_automation.connector_id.id)])
            for wh_id in wh_ids:
                wh_id.write({'active': False})

            # clean token in company_id
            company_id.write({'bearer_token': '', 'external_id': ''})
            msg = f"La aplicación ha sido desinstalada en la tienda {company_id.name}. Se ha removido el acceso a la API de Tiendanube."
            company_id.message_post(body=msg)

        else:
            _logger.error(f"Error: Empresa no encontrada con ID externo {store_id}")
        _logger.info(f"Ejecución del Webhook Evento: app/uninstalled finalizada.")

    except Exception as e:
        _logger.error(f"Error al ejecutar Webhook Evento: app/uninstalled: {str(e)}")
else:
    _logger.info(f"Webhook app/uninstalled. Empresa {record.name} no esta asociada a una tienda en TN.")

_logger.info(f"Ejecutar Webhook category/updated.")
if record.external_id and record.bearer_token:
    try:
        response = base_automation.with_company(record).connector_id.execute_endpoint('CATEG_SINGLE_GET',record=record,data=payload)
        _logger.info(response)
        admin_user = env.ref('base.user_admin')
        if 200 <= response.get('status_code') < 300:
            found_categ_id = env['product.category'].search([('x_external_id', '=', payload.get('id'))])
            if not found_categ_id:
                found_categ_id = env['product.category'].sudo().with_context(not_execute_category_base_automation=True).create(response['values'])
                _logger.info(f"Categoría {found_categ_id.name} sincronizado!.")
            else:
                if found_categ_id.can_sync_from_store():
                    # found_categ_id.mark_as_syncing('store')
                    # _logger.info(f"Categoria {found_categ_id.name} encontrada con ID externo {found_categ_id.x_external_id}. Actualizar")
                    found_categ_id.with_context(not_execute_category_base_automation=True).write(response['values'])
                    _logger.info(f"Categoría {found_categ_id.name} sincronizado!.")
                else:
                    _logger.info(f"Categoría {found_categ_id.id} ya está siendo sincronizada desde Odoo, saltando sincronización.")

            if found_categ_id:
                odoo_model = 'product.category'
                to_create_values = []
                created_field_names = []  # Lista para guardar los nombres de los campos
                # Verificar que el modelo existe en ir.model
                ir_model = env['ir.model'].search([('model', '=', odoo_model)], limit=1)
                if not ir_model:
                    _logger.error(f"El modelo {odoo_model} no existe en el registro de modelos.")
                    raise UserError(f"El modelo {odoo_model} no existe en el registro de modelos.")
                meta_fields = env['solt.api.meta.fields'].search([('model', '=', odoo_model)], limit=1)
                if not meta_fields:
                    _logger.error(f"Meta fields no configurados para el modelo {odoo_model}.")
                    raise UserError(f"Meta fields no configurados para el modelo {odoo_model}.")
                endpoint_code = 'CUSTOM_FIELD_CATEGORY_PROD_GET_ALL'
                _logger.info(f"Endpoint {endpoint_code}")
                response = base_automation.with_company(record).connector_id.execute_endpoint(endpoint_code,record=None)
                _logger.info(response)
                if isinstance(response['values'], list) and 200 <= response.get('status_code') < 300:
                    # verificar si existe la categ
                    for val in response['values']:
                        meta_field_id = env['ir.model.fields'].search([('x_external_id', '=', val['x_external_id'])], limit=1)
                        if not meta_field_id:
                            val['model_id'] = ir_model.id
                            to_create_values.append(Command.create(val))
                            created_field_names.append(val.get('name'))
                        else:
                            _logger.info(f"Meta field con ID Externo {val['x_external_id']} ya fue sincronizado!")

                if to_create_values:
                    meta_fields.sudo().write({'ir_meta_field_ids': to_create_values})
                    meta_fields.add_dynamic_fields_to_extended_view(odoo_model, created_field_names)
                _logger.info(f"Items importadas {len(response['values'])}, Endpoint {endpoint_code}")
                _logger.info(f"Items creados {len(to_create_values)}, Endpoint {endpoint_code}")

                # actualizar los valores campos personalizados
                response = base_automation.with_company(record).connector_id.execute_endpoint('CUSTOM_FIELD_CATEGORY_PROD_GET_VALUES',record=found_categ_id)
                _logger.info(response)
                if 200 <= response.get('status_code') < 300:
                    for response_data, val in zip(response['raw_response'], response['values']):
                        field_odoo_id = env['ir.model.fields'].sudo().search(['|', ('x_external_id', '=', response_data.get('id')), ('x_key', '=', response_data.get('key'))])
                        if field_odoo_id:
                            field_odoo_name = field_odoo_id.name
                            _logger.info(f"Campo personalizado encontrado {field_odoo_name}")
                            val.update({field_odoo_name: response_data.get('value')})
                            found_categ_id.write(val)
                else:
                    _logger.error(f"Error al ejecutar endpoint CUSTOM_FIELD_CATEGORY_PROD_GET_VALUES: {response.get('error_message', '')}")

        # Suspension of API access due to lack of payment
        # se debe suspender todo los endpoints y webhoks
        elif response.get('status_code') == 402:
            _logger.error(f"Error: {response.get('error_message', '')}")
        else:
            _logger.error(f"Error: {response.get('error_message', '')}")
        _logger.info(f"Fin Webhook category/updated!.")

    except Exception as e:
        _logger.error(f"Webhook Categoria de productos: category/updated")
        _logger.error(f"Error al ejecutar endpoint CATEG_SINGLE_GET: {str(e)}")
else:
    _logger.info(f"Webhook category/updated. Empresa {record.name} no esta asociada a una tienda en TN.")

