            if not record.can_sync_to_store():
                _logger.info(f"Cliente {record.id} ya está siendo sincronizada desde la tienda, saltando sincronización.")
                continue
            # Marcar como sincronizando desde Odoo
            record.mark_as_syncing('odoo')

            result = endpoint.with_context(modified_fields=lmodified_fields).execute_request(record=record)
            _logger.info(f"Response: {result}")
            if 200 <= result.get('status_code') < 300 and 'values' in result:
                    record.write(result['values'])
            # Suspension of API access due to lack of payment
            # se debe suspender todo los endpoints y webhoks
            elif result.get('status_code') == 402:
                record.write({
                    'x_date_last_sync': datetime.datetime.now(),
                    'x_state_sync': 'error'
                })
                _logger.error(f"Error Endpoint con código CONTACT_UPDATE: {result.get('error_message', '')}")
            else:
                record.write({
                    'x_date_last_sync': datetime.datetime.now(),
                    'x_state_sync': 'error'
                })
                _logger.error(f"Error Endpoint con código CONTACT_UPDATE: {result.get('error_message', '')}")
        except Exception as e:
            _logger.error(f"Error al ejecutar endpoint CONTACT_UPDATE: {str(e)}")
            record.write({
                'x_date_last_sync': datetime.datetime.now(),
                'x_state_sync': 'error'
            })
    else:
        _logger.info(f"RA Actualizando Cliente. Empresa {env.company.name} no esta asociada a una tienda en TN.")

