        if env.context.get('not_execute_product_base_automation', False):
            _logger.info('not_execute_product_base_automation esta en el contexto. No ejecutar RA.')
            continue
        try:
            if record.standard_price <= 0 and record.product_variant_count == 1:
                raise UserError(f"El costo del producto {record.name} es {record.standard_price}. El costo debe ser mayor que 0.")
            # Verificar si podemos sincronizar
            if not record.can_sync_to_store():
                _logger.info(f"Producto {record.id} ya está siendo sincronizada desde la tienda, saltando sincronización.")
                continue
            # Marcar como sincronizando desde Odoo
            record.mark_as_syncing('odoo')

            # check if product exist in TN by SKU
            sku_response = base_automation.connector_id.execute_endpoint('PRODUCT_SINGLE_SKU_GET',record=record)
            _logger.info(f'Response Endpoint PRODUCT_SINGLE_SKU_GET: {sku_response}')

            # update product in TN
            if 200 <= sku_response.get('status_code') < 300:
                _logger.info('Actualizar producto')
                val = sku_response['values']
                record.write({
                        "x_state_sync": "yes",
                        "x_date_last_sync": datetime.datetime.now(),
                        "x_store_external_id": env.company.external_id,
                        **val
                    })
                #sincronizar variantes
                record.create_product_variants_from_json(sku_response['raw_response'], update_from_store=False)
            # Suspension of API access due to lack of payment
            # se debe suspender todo los endpoints y webhoks
            elif sku_response.get('status_code') == 402:
                record.write({
                    'x_date_last_sync': datetime.datetime.now(),
                    'x_state_sync': 'error'
                })
                _logger.error(f"Error ejecutando endpoint PRODUCT_SINGLE_SKU_GET: {sku_response.get('error_message', '')}")
            elif sku_response.get('status_code') == 422 or  sku_response.get('status_code') != 404:
                _logger.error(f"Error ejecutando endpoint PRODUCT_SINGLE_SKU_GET: {sku_response.get('error_message', '')}")
                raise UserError(f"Error ejecutando endpoint PRODUCT_SINGLE_SKU_GET: {sku_response.get('error_message', '')}")
            # if not found in TN, create it
            elif sku_response.get('status_code') == 404:
                _logger.info('Crear producto')
                response = base_automation.connector_id.execute_endpoint('PRODUCT_CREATE',record=record)
                _logger.info(response)
                if 200 <= response.get('status_code') < 300:
                    record.write(response['values'])

                    if isinstance(response['raw_response'], dict) and response['raw_response'].get('brand', ''):
                        record.product_brand_id.write({
                            "x_state_sync": 'yes',
                            "x_date_last_sync": datetime.datetime.now(),
                            "x_exclud_from_sync": False,
                            "x_store_external_id": env.company.external_id,
                            "company_id": env.company.id
                        })

                    #sincronizar variantes
                    record.create_product_variants_from_json(response['raw_response'], update_from_store=True)
                    # sync images of products
                    # record._sync_product_images_from_json(response['raw_response'])
                    # _logger.info("Imagenes sincronizadas")

                # Suspension of API access due to lack of payment
                # se debe suspender todo los endpoints y webhooks
                elif response.get('status_code') == 402:
                    record.write({
                        'x_date_last_sync': datetime.datetime.now(),
                        'x_state_sync': 'error'
                    })
                    _logger.error(f"Error ejecutando endpoint PRODUCT_CREATE: {response.get('error_message', '')}")
                elif response.get('status_code') == 422 or  response.get('status_code') != 404:
                    _logger.error(f"Error ejecutando endpoint PRODUCT_CREATE: {response.get('error_message', '')}")
                    raise UserError(f"Error ejecutando endpoint PRODUCT_CREATE: {response.get('error_message', '')}")
                else:
                    record.write({
                        'x_date_last_sync': datetime.datetime.now(),
                        'x_state_sync': 'error'
                    })
                    _logger.error(f"Error ejecutando endpoint PRODUCT_CREATE: {response.get('error_message', '')}")
                _logger.info(f"Ejecución del endpoint PRODUCT_CREATE finalizada.")
                _logger.info(f"Producto {record.name} sincronizado!.")
        except Exception as e:
            _logger.error(f"Error al ejecutar endpoint PRODUCT_CREATE: {str(e)}")
            record.write({
                'x_date_last_sync': datetime.datetime.now(),
                'x_state_sync': 'error'
            })
            raise UserError(f"Error: {str(e)}")
