_logger.info(f"RA Ajuste de inventario de una variante producto")
for record in records:
    if env.company.external_id and env.company.bearer_token and record.company_id == env.company:
        name = record.product_id.display_name
        _logger.info(f"Ajuste de inventario a la Variante de producto: {name}")
        if env.context.get('not_execute_quants_base_automation', False):
            _logger.info('not_execute_quants_base_automation esta en el contexto. No ejecutar RA.')
            continue

        try:
            # obtener los campos que se modificaron
            modified_fields = base_automation.with_context(ignore_computed_fields=True)._get_trigger_fields(record)
            _logger.info(f"Campos a actualizar {modified_fields}")

            if modified_fields:
                _logger.info(f'Value de quantity {record.quantity}')

                quantity = 0
                request_data = {
                    "action": "replace",
                    "value": quantity,
                    "id": record.product_id.x_external_id,
                    "location_id": record.warehouse_id.x_external_id
                }
                inventory_level = record.product_id._get_total_inventory_level_product_api(warehouse_external_id=record.warehouse_id.x_external_id)
                if inventory_level:
                    quantity = inventory_level[0].get("stock")

                request_data.update({"value": quantity})

                if quantity == 0:  # establecer en 0
                    code = 'VARIANT_PROD_REPLACE_STOCKOUT_POST'
                if quantity > 0:
                    code = 'VARIANT_PROD_REPLACE_STOCK_POST'
                if quantity < 0:
                    _logger.info('quitar stock')

                endpoint = env['solt.api.endpoint'].search([('code', '=', code), ('connector_id', '=', base_automation.connector_id.id)], limit=1)
                if not endpoint:
                    msg = f"Endpoint con código {code} no configurado, para actualizar el stock de los productos."
                    _logger.info(msg)
                    raise UserError(msg)
                # Verificar si podemos sincronizar
                if not record.product_tmpl_id.can_sync_to_store():
                    _logger.info(
                        f"Producto con ID {record.product_tmpl_id.id} ya está siendo sincronizada desde la tienda, saltando sincronización.")
                    continue
                # Marcar como sincronizando desde Odoo
                record.product_tmpl_id.mark_as_syncing('odoo')
                response = endpoint.execute_request(record=record, request_data=request_data)
                _logger.info(response)
                if 200 <= response.get('status_code') < 300:
                    if isinstance(response['values'], list):
                        for vals in response['values']:
                            record.product_id.write(vals)
                # Suspension of API access due to lack of payment
                # se debe suspender todo los endpoints y webhoks
                elif response.get('status_code') == 402:
                        record.product_id.write({
                            'x_date_last_sync': datetime.datetime.now(),
                            'x_state_sync': 'error'
                        })
                        _logger.error(f"Error ejecutando endpoint {code}: {response.get('error_message', '')}")
                elif response.get('status_code') == 422 or response.get('status_code') != 404:
                    _logger.error(f"Error ejecutando endpoint {code}: {response.get('error_message', '')}")
                    raise UserError(f"Error ejecutando endpoint {code}: {response.get('error_message', '')}")
                else:
                    record.product_id.write({
                        'x_date_last_sync': datetime.datetime.now(),
                        'x_state_sync': 'error'
                    })
                    _logger.error(f"Error ejecutando endpoint {code}: {response.get('error_message', '')}")
                _logger.info(f"Ejecución del endpoint {code} finalizada.")
                _logger.info(f"Ajuste de inventario a Variante de producto {name} sincronizado!.")
        except Exception as e:
            _logger.error(f"Error al Ajuste de inventario a Variante de producto {name}: {str(e)}")
            record.product_id.write({
                'x_date_last_sync': datetime.datetime.now(),
                'x_state_sync': 'error'
            })
            raise UserError(f"Error: {str(e)}")
    else:
        _logger.info(f"RA Ajuste de inventario de una variante producto. Empresa {env.company.name} no esta asociada a una tienda en TN.")

