RESOURCE_TO_ODOO_MODEL = {
    'CUSTOM_FIELD_PROD_GET_ALL': 'product.template',
    'CUSTOM_FIELD_VARIANT_GET_ALL': 'product.product',
    'CUSTOM_FIELD_ORDERS_GET_ALL': 'sale.order',
    'CUSTOM_FIELD_CUSTOMER_GET_ALL': 'res.partner',
    'CUSTOM_FIELD_CATEGORY_PROD_GET_ALL': 'product.category'
}
if not env.company.external_id or not env.company.bearer_token:
    raise UserError(f"La empresa {env.company.name} no está sincronizada con una tienda.")
action_id = env['ir.actions.server'].search([('use_for_initial_import', '=', True)], limit=1)
if action_id and action_id.connector_id:
    for endpoint_code, odoo_model in RESOURCE_TO_ODOO_MODEL.items():
        _logger.info(f"Endpoint {endpoint_code}")
        created_field_names = []  # Lista para guardar los nombres de los campos
        response = action_id.connector_id.execute_endpoint(endpoint_code,record=record)
        _logger.info(response)
        to_create_values = []
        # Verificar que el modelo existe en ir.model
        ir_model = env['ir.model'].search([('model', '=', odoo_model)], limit=1)
        if not ir_model:
            _logger.error(f"El modelo {odoo_model} no existe en el registro de modelos.")
            raise UserError(f"El modelo {odoo_model} no existe en el registro de modelos.")
        meta_fields = env['solt.api.meta.fields'].search([('model', '=', odoo_model)], limit=1)
        if not meta_fields:
            _logger.error(f"Meta fields no configurados para el modelo {odoo_model}.")
            raise UserError(f"Meta fields no configurados para el modelo {odoo_model}.")
        if isinstance(response['values'], list) and 200 <= response.get('status_code') < 300:
            # verificar si existe la categ
            for val in response['values']:
                meta_field_id = env['ir.model.fields'].search([('x_external_id', '=', val['x_external_id'])], limit=1)
                if not meta_field_id:
                    val['model_id'] = ir_model.id
                    to_create_values.append(Command.create(val))
                    created_field_names.append(val.get('name'))
                else:
                    _logger.info(f"Campo meta con ID Externo {val['x_external_id']} ya fue sincronizado!")
        if to_create_values:
            meta_fields.sudo().write({'ir_meta_field_ids': to_create_values})
            meta_fields.add_dynamic_fields_to_extended_view(odoo_model, created_field_names)
        _logger.info(f"Items importadas {len(response['values'])}, Endpoint {endpoint_code}")
        _logger.info(f"Items creados {len(to_create_values)}, Endpoint {endpoint_code}")
else:
    _logger.error("Conector no configurado")

if not env.company.external_id or not env.company.bearer_token:
    raise UserError(f"La empresa {env.company.name} no está sincronizada con una tienda.")
action_id = env['ir.actions.server'].search([('use_for_initial_import', '=', True)], limit=1)
if action_id and action_id.connector_id:
    res = action_id.connector_id.execute_endpoint('CATEG_ALL_GET',record=record)
    _logger.info(res)
    to_create_values = []
    raw_response = []
    categ_ids = env['product.category'].sudo()
    if isinstance(res['raw_response'], dict) and 'items' in res['raw_response']:  # paginado
        raw_response = res['raw_response'].get('items')
    elif isinstance(res['raw_response'], list):
        raw_response = res['raw_response']
    if isinstance(res['values'], list):
        # verificar si existe la categ
        for val in res['values']:
            categ_id = env['product.category'].search([('x_external_id', '=', val['x_external_id'])], limit=1)
            if not categ_id:
                to_create_values.append(val)
            else:
                categ_ids |= categ_id
                _logger.info(f"Categoria con ID Externo {val['x_external_id']} ya fue sincronizado!")

    if to_create_values:
        _logger.info(f"A crear {to_create_values}")
        categ_ids |= env['product.category'].sudo().with_context(not_execute_category_base_automation=True).create(to_create_values)
    _logger.info(f"Items importadas {len(res['values'])}")

    # actualizar valores de los campos personalizados
    if categ_ids:
        for categ in categ_ids:
            response = action_id.connector_id.execute_endpoint('CUSTOM_FIELD_CATEGORY_PROD_GET_VALUES',record=categ)
            _logger.info(response)
            if 200 <= response.get('status_code') < 300:
                for response_data, val in zip(response['raw_response'], response['values']):
                    field_odoo_id = env['ir.model.fields'].sudo().search(['|', ('x_external_id', '=', response_data.get('id')), ('x_key', '=', response_data.get('key'))])
                    if field_odoo_id:
                        field_odoo_name = field_odoo_id.name
                        _logger.info(f"Campo personalizado encontrado {field_odoo_name}")
                        val.update({field_odoo_name: response_data.get('value')})
                        categ.write(val)
            else:
                _logger.error(f"Error al ejecutar endpoint CUSTOM_FIELD_CATEGORY_PROD_GET_VALUES: {response.get('error_message', '')}")

    # crear los webhooks y publicarlos
    _logger.info(f"Crear los webhooks")
    for wh_event in ["category/created", "category/updated", "category/deleted"]:
        # verificar si fue creado
        wh_event_id = env['solt.register.webhook'].with_context(active_test=False).search([('event', '=', wh_event), ('company_id', '=', env.company.id)])
        if wh_event_id and wh_event_id.x_state_sync == 'yes':
            continue
        wh_event_id._register_webhook(action_id.connector_id)
else:
    _logger.error("Conector no configurado")

