if not env.company.external_id or not env.company.bearer_token:
    raise UserError(f"La empresa {env.company.name} no está sincronizada con una tienda.")
action_id = env['ir.actions.server'].search([('use_for_initial_import', '=', True)], limit=1)
if action_id and action_id.connector_id:
    res = action_id.connector_id.execute_endpoint('STOCK_ALL_GET',record=record)
    _logger.info(res)
    to_create_values = []
    stock_warehouse_ids = None
    if isinstance(res['values'], list):
        # verificar si existe
        for response_data, val in zip(res['raw_response'], res['values']):
            stock_warehouse_id = env['stock.warehouse'].search([('x_external_id', '=', val['x_external_id'])], limit=1)
            if not stock_warehouse_id:
                create_val = {
                    'tn_name': response_data.get('id') + ' | ' + stock_warehouse_id.convert_translated_field_to_odoo_format(response_data.get('name'), split_code=False),
                    'company_id': env.company.id,
                    'response_body': response_data,
                    'response_mapping': val
                }
                to_create_values.append(create_val)
            else:
                _logger.info(f"Almacén con ID Externo {val['x_external_id']} ya fue sincronizado!")
                wh_mapping_id = env['solt.warehouse.sync.mapping'].search([('warehouse_id', '=', stock_warehouse_id.id), ('company_id', '=', env.company.id)])
                if not wh_mapping_id:
                    create_val = {
                        'tn_name': response_data.get('id') + ' | ' + stock_warehouse_id.convert_translated_field_to_odoo_format(response_data.get('name'), split_code=False),
                        'warehouse_id': stock_warehouse_id.id,
                        'company_id': env.company.id,
                        'response_body': response_data,
                        'response_mapping': val
                    }
                    # crear entrada en WH mapping
                    wh_mapping_id = env['solt.warehouse.sync.mapping'].with_company(env.company).sudo().create(create_val)
                    _logger.info(f"Creada mapping de almacen {wh_mapping_id.display_name}")
                else:
                    _logger.info(f"Mapping de almacen {wh_mapping_id.display_name} ya fue sincronizado!")

    if to_create_values:
        stock_warehouse_ids = env['solt.warehouse.sync.mapping'].sudo().with_company(env.company).create(to_create_values)
    _logger.info(f"Items importadas {len(res['values'])}")
else:
    _logger.error("Conector no configurado")

if not env.company.external_id or not env.company.bearer_token:
    raise UserError(f"La empresa {env.company.name} no está sincronizada con una tienda.")
action_id = env['ir.actions.server'].search([('use_for_initial_import', '=', True)], limit=1)
_logger.info(env.context.get('default_connector_id', False))
if action_id and action_id.connector_id:
    res = action_id.connector_id.execute_endpoint('PRODUCT_ALL_GET',record=record)
    to_create_values = []
    to_write_values = []
    product_ids = env['product.template'].sudo()
    sku_found_product_ids = env['product.template'].sudo()
    if isinstance(res['values'], list):
        # verificar si existe el producto template
        for val in res['values']:
            product_id = env['product.template'].search([('x_external_id', '=', val['x_external_id'])], limit=1)
            if product_id:
                # product_ids |= product_id
                _logger.info(f"Producto con ID Externo {val['x_external_id']} ya fue sincronizado!")
                continue
            _logger.info(val)
            if val['default_code'] or val['name']:
                if val['default_code']:
                    domain = [('default_code', '=', val['default_code'])]
                else:
                    domain = [('name', '=', val['name'])]
                product_id = env['product.template'].with_company(env.company).search(domain, limit=1)
                if not product_id:
                    _logger.info(f"Producto con sku {val['default_code']} no encontrado!")
                    to_create_values.append({
                        "x_state_sync": "yes",
                        "x_date_last_sync": datetime.datetime.now(),
                        "x_store_external_id": env.company.external_id,
                        **val
                    })
                else:
                    product_id.with_context(not_execute_product_base_automation=True).write({
                        "x_state_sync": "yes",
                        "x_date_last_sync": datetime.datetime.now(),
                        "x_store_external_id": env.company.external_id,
                        **val
                    })
                    sku_found_product_ids |= product_id
                    _logger.info(f"Producto con sku {val['default_code']} encontrado y actualizado!")
    sync_values = {
        "x_state_sync": "yes",
        "x_date_last_sync": datetime.datetime.now(),
        "x_store_external_id": env.company.external_id
    }
    if to_create_values:
        product_ids = env['product.template'].sudo().with_context(not_execute_product_base_automation=True).create(to_create_values)
        # if product_ids: # actualizar sincronizacion
        #     product_ids.write(sync_values)
    _logger.info(f"Items importadas {len(res['values'])}")
    _logger.info(f"Items creados {len(to_create_values)}")

    # crear variantes de productos
    if product_ids or sku_found_product_ids:
        all_products = product_ids | sku_found_product_ids
        raw_response = []
        if isinstance(res['raw_response'], dict) and 'items' in res['raw_response']:  # paginado
            raw_response = res['raw_response'].get('items')
        elif isinstance(res['raw_response'], list):
            raw_response = res['raw_response']
        product_variant_ids = all_products.with_context(not_execute_product_base_automation=True).create_product_variants_from_json(raw_response)
        _logger.info(f"Variantes creadas {len(product_variant_ids)}")
        # sync images of products
        # all_products._sync_product_images_from_json(raw_response)
        # _logger.info("Imagenes sincronizadas")

        # ajuste de inventario
        product_ids.with_context(not_execute_product_base_automation=True)._create_or_write_stock_quants_from_json(raw_response)
        _logger.info("END ajuste de inventario.")

        # actualizar valores de los campos personalizados productos
        for product in all_products:
            _logger.info("Endpoint CUSTOM_FIELD_PROD_GET_VALUES")
            response = action_id.connector_id.execute_endpoint('CUSTOM_FIELD_PROD_GET_VALUES',record=product)
            _logger.info(response)
            if 200 <= response.get('status_code') < 300:
                for response_data, val in zip(response['raw_response'], response['values']):
                    field_odoo_id = env['ir.model.fields'].sudo().search(['|', ('x_external_id', '=', response_data.get('id')), ('x_key', '=', response_data.get('key'))])
                    if field_odoo_id:
                        field_odoo_name = field_odoo_id.name
                        _logger.info(f"Campo personalizado encontrado {field_odoo_name}")
                        val.update({field_odoo_name: response_data.get('value')})
                        product.write(val)
            else:
                _logger.error(f"Error al ejecutar endpoint CUSTOM_FIELD_PROD_GET_VALUES: {response.get('error_message', '')}")

        # actualizar valores de los campos personalizados variantes
        if product_variant_ids:
            for variant in product_variant_ids:
                _logger.info("Endpoint CUSTOM_FIELD_VARIANT_GET_VALUES")
                response = action_id.connector_id.execute_endpoint('CUSTOM_FIELD_VARIANT_GET_VALUES',record=variant)
                _logger.info(response)
                if 200 <= response.get('status_code') < 300:
                    for response_data, val in zip(response['raw_response'], response['values']):
                        field_odoo_id = env['ir.model.fields'].sudo().search(['|', ('x_external_id', '=', response_data.get('id')), ('x_key', '=', response_data.get('key'))])
                        if field_odoo_id:
                            field_odoo_name = field_odoo_id.name
                            _logger.info(f"Campo personalizado encontrado {field_odoo_name}")
                            val.update({field_odoo_name: response_data.get('value')})
                            variant.write(val)
                else:
                    _logger.error(f"Error al ejecutar endpoint CUSTOM_FIELD_VARIANT_GET_VALUES: {response.get('error_message', '')}")
else:
    _logger.error("Conector no configurado")

if not env.company.external_id or not env.company.bearer_token:
    raise UserError(f"La empresa {env.company.name} no está sincronizada con una tienda.")
action_id = env['ir.actions.server'].search([('use_for_initial_import', '=', True)], limit=1)
_logger.info(env.context.get('default_connector_id', False))
if action_id and action_id.connector_id:
    admin_user = env.ref('base.user_admin')
    res = action_id.connector_id.with_company(env.company).with_user(admin_user).execute_endpoint('SALE_ORDER_GET_ALL',record=record)
    _logger.info(res)
    to_create_values = []
    order_ids = env['sale.order'].sudo()
    order_response_dict = {}
    raw_response = []
    if isinstance(res['raw_response'], dict) and 'items' in res['raw_response']:  # paginado
        raw_response = res['raw_response'].get('items')
    elif isinstance(res['raw_response'], list):
        raw_response = res['raw_response']
    _logger.info(f"Response {res['values']}")
    if isinstance(res['values'], list):
        # verificar si existe la orden
        for val in res['values']:
            _logger.info(f"Val {val}")
            order_id = env['sale.order'].with_company(env.company).search([('x_external_id', '=', val['x_external_id'])], limit=1)
            if not order_id:
                # buscar fulfillment order para completar algunos datos como la Fecha de entrega
                data = {'id': val.get('x_external_id')}
                response = action_id.connector_id.with_company(env.company).with_user(admin_user).execute_endpoint('SALE_ORDER_GET_SINGLE',record=record, data=data)
                _logger.info(f"SALE_ORDER_GET_SINGLE {response}")
                if 200 <= response.get('status_code') < 300:
                    if isinstance(response['values'], list):
                        value = response['values'][0]
                    if isinstance(response['values'], dict):
                        value = response['values']
                    commitment_date = value.get('commitment_date')
                    val['commitment_date'] = commitment_date
                    to_create_values.append(value)
                    order_response_dict[str(val.get('x_external_id'))] = response['raw_response']
                else:
                    _logger.error(f"Error al ejecutar endpoint SALE_ORDER_GET_SINGLE: {response.get('error_message', '')}")
            else:
                order_ids |= order_id
                _logger.info(f"Orden con ID Externo {val['x_external_id']} ya fue sincronizado!")
    if to_create_values:
        _logger.info(f'to create: {to_create_values}')
        order_ids = env['sale.order'].with_context(
            mail_create_nosubscribe=True
        ).with_company(env.company).sudo().create(to_create_values)
    _logger.info(f"Items importadas {len(res['values'])}")
    _logger.info(f"Items creados {len(order_ids)}")

    # actualizar valores de los campos personalizados
    if order_ids:
        _logger.info("Actualizar los campos personalizados")
        for order in order_ids:
            response = action_id.connector_id.execute_endpoint('CUSTOM_FIELD_ORDERS_GET_VALUES',record=order)
            _logger.info(response)
            if 200 <= response.get('status_code') < 300:
                for response_data, val in zip(response['raw_response'], response['values']):
                    field_odoo_id = env['ir.model.fields'].sudo().search(['|', ('x_external_id', '=', response_data.get('id')), ('x_key', '=', response_data.get('key'))])
                    if field_odoo_id:
                        field_odoo_name = field_odoo_id.name
                        _logger.info(f"Campo personalizado encontrado {field_odoo_name}")
                        val.update({field_odoo_name: response_data.get('value')})
                        order.write(val)
            else:
                _logger.error(f"Error al ejecutar endpoint CUSTOM_FIELD_ORDERS_GET_VALUES: {response.get('error_message', '')}")
            if order.state == 'draft':
                _logger.info(f"Orden a confirmar {order.order_number}")
                order.tiendanube_create_initial_stock_quants_from_order(order_response_dict)
                order.action_confirm()
                order.tiendanube_sync_picking_from_order(order_response_dict)
                # si la orden fue entregada
                if order.delivery_status == 'full':
                    order.action_lock()

    # crear los webhooks y publicarlos
    _logger.info(f"Crear los webhooks")
    for wh_event in ["order/created", "order/updated", "order/cancelled", "order/fulfilled", "order/paid", "order/edited", "fulfillment/updated"]:
        # verificar si fue creado
        wh_event_id = env['solt.register.webhook'].with_context(active_test=False).search([('event', '=', wh_event), ('company_id', '=', env.company.id)])
        if wh_event_id and wh_event_id.x_state_sync == 'yes':
            continue
        wh_event_id._register_webhook(action_id.connector_id)
else:
    _logger.error("Conector no configurado")

if not env.company.external_id or not env.company.bearer_token:
    raise UserError(f"La empresa {env.company.name} no está sincronizada con una tienda.")
action_id = env['ir.actions.server'].search([('use_for_initial_export', '=', True)], limit=1)
_logger.info(env.context.get('default_connector_id', False))
if action_id and action_id.connector_id:
    product_ids = env['product.template'].sudo()
    to_create_variant_product_ids = env['product.product'].sudo()
    # buscar productos a exportar
    product_to_export_ids = env['product.template'].with_company(env.company).search([
        ('sale_ok', '=', True),
        ('x_exclud_from_sync', '=', False),  # no excluido
        ('x_external_id', 'in', [False, '']), # no sincronizado
        ('company_id', '=', env.company.id),
    ])
    _logger.info("Creando productos en TN...")
    for product in product_to_export_ids:
        if product.standard_price <= 0 and product.product_variant_count == 1:
            raise UserError(f"El costo del producto {product.name} es {product.standard_price}. El costo debe ser mayor que 0.")
        _logger.info(f'Crear producto en TN: {product.name}')
        response = action_id.connector_id.execute_endpoint('PRODUCT_CREATE',record=product)
        _logger.info(response)
        if 200 <= response.get('status_code') < 300:
            product.write(response['values'])

            if isinstance(response['raw_response'], dict) and response['raw_response'].get('brand', ''):
                product.product_brand_id.write({
                    "x_state_sync": 'yes',
                    "x_date_last_sync": datetime.datetime.now(),
                    "x_exclud_from_sync": False,
                    "x_store_external_id": env.company.external_id,
                    "company_id": env.company.id
                })
            to_create_variant_product_ids |= product.with_context(not_execute_product_base_automation=True).create_product_variants_from_json(response['raw_response'], update_from_store=True)
            product_ids |= product
        else:
            product.write({
                'x_date_last_sync': datetime.datetime.now(),
                'x_state_sync': 'error'
            })
            _logger.error(f"Error ejecutando endpoint PRODUCT_CREATE: {response.get('error_message', '')}")

    _logger.info(f"Productos procesados {len(product_to_export_ids)}")
    _logger.info(f"Productos sincronizados {len(product_ids)}")
    _logger.info(f"Variantes sincronizadas {len(to_create_variant_product_ids)}")

    # actualizar valores de los campos personalizados productos
    if product_ids:
        all_products = product_ids
        for product in all_products:
            _logger.info("Endpoint CUSTOM_FIELD_PROD_GET_VALUES")
            response = action_id.connector_id.execute_endpoint('CUSTOM_FIELD_PROD_GET_VALUES',record=product)
            _logger.info(response)
            if 200 <= response.get('status_code') < 300:
                for response_data, val in zip(response['raw_response'], response['values']):
                    field_odoo_id = env['ir.model.fields'].sudo().search(['|', ('x_external_id', '=', response_data.get('id')), ('x_key', '=', response_data.get('key'))])
                    if field_odoo_id:
                        field_odoo_name = field_odoo_id.name
                        _logger.info(f"Campo personalizado encontrado {field_odoo_name}")
                        val.update({field_odoo_name: response_data.get('value')})
                        product.write(val)
            else:
                _logger.error(f"Error al ejecutar endpoint CUSTOM_FIELD_PROD_GET_VALUES: {response.get('error_message', '')}")

    # actualizar valores de los campos personalizados variantes
    if to_create_variant_product_ids:
        product_variant_ids = to_create_variant_product_ids
        for variant in product_variant_ids:
            _logger.info("Endpoint CUSTOM_FIELD_VARIANT_GET_VALUES")
            response = action_id.connector_id.execute_endpoint('CUSTOM_FIELD_VARIANT_GET_VALUES',record=variant)
            _logger.info(response)
            if 200 <= response.get('status_code') < 300:
                for response_data, val in zip(response['raw_response'], response['values']):
                    field_odoo_id = env['ir.model.fields'].sudo().search(['|', ('x_external_id', '=', response_data.get('id')), ('x_key', '=', response_data.get('key'))])
                    if field_odoo_id:
                        field_odoo_name = field_odoo_id.name
                        _logger.info(f"Campo personalizado encontrado {field_odoo_name}")
                        val.update({field_odoo_name: response_data.get('value')})
                        variant.write(val)
            else:
                _logger.error(f"Error al ejecutar endpoint CUSTOM_FIELD_VARIANT_GET_VALUES: {response.get('error_message', '')}")
else:
    _logger.error("Conector no configurado")

if not env.company.external_id or not env.company.bearer_token:
    raise UserError(f"La empresa {env.company.name} no está sincronizada con una tienda.")
action_id = env['ir.actions.server'].search([('use_for_initial_import', '=', True)], limit=1)
_logger.info(env.context.get('default_connector_id', False))
if action_id and action_id.connector_id:
    res = action_id.connector_id.execute_endpoint('PRODUCT_ALL_GET',record=record)
    to_create_values = []
    to_write_values = []
    product_ids = env['product.template'].sudo()
    sku_found_product_ids = env['product.template'].sudo()
    if isinstance(res['values'], list):
        # verificar si existe el producto template
        for val in res['values']:
            product_id = env['product.template'].search([('x_external_id', '=', val['x_external_id'])], limit=1)
            if product_id:
                _logger.info(f"Producto con ID Externo {val['x_external_id']} ya fue sincronizado!")
                continue
            _logger.info(val)
            if val['default_code'] or val['name']:
                if val['default_code']:
                    domain = [('default_code', '=', val['default_code'])]
                else:
                    domain = [('name', '=', val['name'])]
                product_id = env['product.template'].with_company(env.company).search(domain, limit=1)
                _logger.info(product_id)
                if not product_id:
                    _logger.info(f"Producto con sku {val['default_code']} no encontrado!")
                    to_create_values.append({
                        "x_state_sync": "yes",
                        "x_date_last_sync": datetime.datetime.now(),
                        "x_store_external_id": env.company.external_id,
                        **val
                    })
                else:
                    product_id.with_context(not_execute_product_base_automation=True).write({
                        "x_state_sync": "yes",
                        "x_date_last_sync": datetime.datetime.now(),
                        "x_store_external_id": env.company.external_id,
                        **val
                    })
                    sku_found_product_ids |= product_id
                    _logger.info(f"Producto con sku {val['default_code']} encontrado y actualizado!")
    sync_values = {
        "x_state_sync": "yes",
        "x_date_last_sync": datetime.datetime.now(),
        "x_store_external_id": env.company.external_id
    }
    if to_create_values:
        product_ids = env['product.template'].sudo().with_context(not_execute_product_base_automation=True).create(to_create_values)
    _logger.info(f"Items importadas {len(res['values'])}")
    _logger.info(f"Items creados {len(to_create_values)}")

    # crear variantes de productos
    if product_ids or sku_found_product_ids:
        all_products = product_ids | sku_found_product_ids
        raw_response = []
        if isinstance(res['raw_response'], dict) and 'items' in res['raw_response']:  # paginado
            raw_response = res['raw_response'].get('items')
        elif isinstance(res['raw_response'], list):
            raw_response = res['raw_response']
        product_variant_ids = all_products.with_context(not_execute_product_base_automation=True).create_product_variants_from_json(raw_response)
        _logger.info(f"Variantes creadas {len(product_variant_ids)}")

        # actualizar valores de los campos personalizados productos
        for product in all_products:
            _logger.info("Endpoint CUSTOM_FIELD_PROD_GET_VALUES")
            response = action_id.connector_id.execute_endpoint('CUSTOM_FIELD_PROD_GET_VALUES',record=product)
            _logger.info(response)
            if 200 <= response.get('status_code') < 300:
                for response_data, val in zip(response['raw_response'], response['values']):
                    field_odoo_id = env['ir.model.fields'].sudo().search(['|', ('x_external_id', '=', response_data.get('id')), ('x_key', '=', response_data.get('key'))])
                    if field_odoo_id:
                        field_odoo_name = field_odoo_id.name
                        _logger.info(f"Campo personalizado encontrado {field_odoo_name}")
                        val.update({field_odoo_name: response_data.get('value')})
                        product.write(val)
            else:
                _logger.error(f"Error al ejecutar endpoint CUSTOM_FIELD_PROD_GET_VALUES: {response.get('error_message', '')}")

        # actualizar valores de los campos personalizados variantes
        if product_variant_ids:
            for variant in product_variant_ids:
                _logger.info("Endpoint CUSTOM_FIELD_VARIANT_GET_VALUES")
                response = action_id.connector_id.execute_endpoint('CUSTOM_FIELD_VARIANT_GET_VALUES',record=variant)
                _logger.info(response)
                if 200 <= response.get('status_code') < 300:
                    for response_data, val in zip(response['raw_response'], response['values']):
                        field_odoo_id = env['ir.model.fields'].sudo().search(['|', ('x_external_id', '=', response_data.get('id')), ('x_key', '=', response_data.get('key'))])
                        if field_odoo_id:
                            field_odoo_name = field_odoo_id.name
                            _logger.info(f"Campo personalizado encontrado {field_odoo_name}")
                            val.update({field_odoo_name: response_data.get('value')})
                            variant.write(val)
                else:
                    _logger.error(f"Error al ejecutar endpoint CUSTOM_FIELD_VARIANT_GET_VALUES: {response.get('error_message', '')}")
else:
    _logger.error("Conector no configurado")
